props.default:
forwardRef<HTMLTableSectionElement, CTableHeadProps>(
  ({ children, className, color, theme, ...rest }, ref) => {
    return (
      <thead
        className={
          classNames(
            {
              [`theme-${theme ?? color}`]: theme ?? color,
            },
            className
          ) || undefined
        }
        {...rest}
        ref={ref}
      >
        {children}
      </thead>
    )
  }
)

